// ─────────────────────────────────────────────────────────────
// SECTION: Seed Function
// PURPOSE: Insert exercises using findOrCreate by exercise_key
// WHY: Idempotent seeding per CEO Ruling V2.0
// ─────────────────────────────────────────────────────────────

/**
 * Seed free-exercise-db exercises using exercise_key-based findOrCreate.
 * Safe to re-run: will not duplicate existing exercises.
 */
export async function seedFreeExerciseDb() {
  let created = 0;
  let skipped = 0;
  let failed = 0;

  console.log(`Starting free-exercise-db seed: ${ALL_FREE_EXERCISE_DB.length} exercises...`);

  for (const exerciseData of ALL_FREE_EXERCISE_DB) {
    const { id, ...data } = exerciseData;

    try {
      const [, wasCreated] = await Exercise.findOrCreate({
        where: { exercise_key: data.exercise_key },
        defaults: { id, ...data },
      });

      if (wasCreated) {
        created++;
      } else {
        skipped++;
      }
    } catch (error) {
      // If exercise_key column doesn't exist yet, fall back to name
      if (error.message?.includes('exercise_key')) {
        try {
          const [, wasCreated] = await Exercise.findOrCreate({
            where: { name: data.name },
            defaults: { id, ...data },
          });
          if (wasCreated) created++;
          else skipped++;
        } catch (nameError) {
          console.error(`  Failed to seed ${data.name}:`, nameError.message);
          failed++;
        }
      } else {
        console.error(`  Failed to seed ${data.name}:`, error.message);
        failed++;
      }
    }
  }

  console.log(`\nFree-exercise-db seed complete:`);
  console.log(`  Created: ${created}`);
  console.log(`  Skipped (already existed): ${skipped}`);
  console.log(`  Failed: ${failed}`);
  console.log(`  Total attempted: ${ALL_FREE_EXERCISE_DB.length}`);

  return { created, skipped, failed, total: ALL_FREE_EXERCISE_DB.length };
}

// ─────────────────────────────────────────────────────────────
// SECTION: Self-executing main
// PURPOSE: Allow direct execution: node backend/seeders/20260321-seed-free-exercise-db.mjs
// ─────────────────────────────────────────────────────────────
const isDirectRun = process.argv[1]?.includes('seed-free-exercise-db');
if (isDirectRun) {
  import('../database.mjs')
    .then(async ({ default: sequelize }) => {
      console.log('Connecting to database...');
      await sequelize.authenticate();
      console.log('Connected. Running seed...\n');

      const result = await seedFreeExerciseDb();
      console.log('\nDone:', result);
      process.exit(0);
    })
    .catch((e) => {
      console.error('Seed failed:', e);
      process.exit(1);
    });
}
